To achieve this, you can use HTML, CSS, and JavaScript. Below is an example of how you can draw a hexagon on a canvas and change its color when you hover over it.

### HTML
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Hexagon Hover Effect</title>
<style>
  canvas {
    border: 1px solid black;
  }
</style>
</head>
<body>
<canvas id="hexagonCanvas" width="400" height="400"></canvas>
<script src="hexagon.js"></script>
</body>
</html>
```

### JavaScript (hexagon.js)
```javascript
document.addEventListener('DOMContentLoaded', function() {
    const canvas = document.getElementById('hexagonCanvas');
    const ctx = canvas.getContext('2d');

    // Hexagon properties
    const hexagonSize = 100;
    const hexagonX = canvas.width / 2;
    const hexagonY = canvas.height / 2;

    // Draw a hexagon
    function drawHexagon(x, y, size, color) {
        ctx.beginPath();
        ctx.moveTo(x, y - size);
        ctx.lineTo(x + size * Math.sqrt(3) / 2, y - size / 2);
        ctx.lineTo(x + size * Math.sqrt(3) / 2, y + size / 2);
        ctx.lineTo(x, y + size);
        ctx.lineTo(x - size * Math.sqrt(3) / 2, y + size / 2);
        ctx.lineTo(x - size * Math.sqrt(3) / 2, y - size / 2);
        ctx.closePath();
        ctx.fillStyle = color;
        ctx.fill();
    }

    // Initial draw
    drawHexagon(hexagonX, hexagonY, hexagonSize, 'blue');

    // Mouse event listeners
    canvas.addEventListener('mousemove', function(event) {
        const rect = canvas.getBoundingClientRect();
        const mouseX = event.clientX - rect.left;
        const mouseY = event.clientY - rect.top;

        // Check if the mouse is over the hexagon
        if (isPointInHexagon(mouseX, mouseY, hexagonX, hexagonY, hexagonSize)) {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawHexagon(hexagonX, hexagonY, hexagonSize, 'red');
        } else {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawHexagon(hexagonX, hexagonY, hexagonSize, 'blue');
        }
    });

    // Function to check if a point is inside a hexagon
    function isPointInHexagon(px, py, hx, hy, size) {
        const halfHeight = size;
        const halfWidth = size * Math.sqrt(3) / 2;
        const x = px - hx;
        const y = py - hy;

        // Check if the point is within the bounding box of the hexagon
        if (Math.abs(x) > halfWidth || Math.abs(y) > halfHeight) {
            return false;
        }

        // Check if the point is within the hexagon
        if (y < 0) {
            return (x * Math.sqrt(3) / 2) < (halfHeight - y);
        } else {
            return (x * Math.sqrt(3) / 2) < (halfHeight + y);
        }
    }
});
```

### Explanation
- **HTML**: The HTML file sets up a canvas element and includes a script tag to link to the JavaScript file.
- **CSS**: Basic styling to add a border around the canvas.
- **JavaScript**:
  - The `drawHexagon` function draws a hexagon on the canvas.
  - The `isPointInHexagon` function checks if a given point is inside the hexagon.
  - The `mousemove` event listener checks if the mouse is over the hexagon and changes its color accordingly.

This code will draw a blue hexagon on the canvas and change its color to red when you hover over it.
